<?php
 namespace clagiordano\weblibs\configmanager; class ConfigManager { private $configData = null; private $configFilePath = null; public function __construct($configFilePath = null) { return $this->loadConfig($configFilePath); } public function loadConfig($configFilePath = null) { if (!is_null($configFilePath)) { $this->configFilePath = $configFilePath; if (file_exists($configFilePath)) { $this->configData = require $configFilePath; } } return $this; } public function saveConfigFile($configFilePath = null, $autoReloadConfig = false) { if (is_null($configFilePath)) { $configFilePath = $this->configFilePath; } $configFileContent = "<?php\n\n"; $configFileContent .= "return "; $configFileContent .= var_export($this->configData, true); $configFileContent .= ";\n\n"; try { file_put_contents($configFilePath, $configFileContent); } catch (\Exception $exc) { throw new \RuntimeException( __METHOD__ . ": Failed to write config file to path '{$configFilePath}'" ); } if ($autoReloadConfig) { $this->loadConfig($configFilePath); } return $this; } private function & getValuePointer($configPath) { $configData =& $this->configData; $parts = explode('.', $configPath); $length = count($parts); for ($i = 0; $i < $length; $i++) { if (!isset($configData[ $parts[ $i ] ])) { $configData[ $parts[ $i ] ] = ($i === $length) ? [] : null; } $configData = &$configData[ $parts[ $i ] ]; } return $configData; } public function getValue($configPath, $defaultValue = null) { $stored = $this->getValuePointer($configPath); return is_null($stored) ? $defaultValue : $stored; } public function existValue($keyValue) { return !is_null($this->getValue($keyValue)); } public function setValue($configPath, $newValue) { $configData = &$this->getValuePointer($configPath); $configData = $newValue; return $this; } } 